import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

# ---------------------------------------------------------------------------
# Hand-authored PTX GEMM kernel.
#
# Computes C(M,N) = A(M,K) @ B(K,N), all tensors row-major / contiguous
# float32.  Tiling: 32x32 output tile per CTA, block = (32,32,1) = 1024
# threads, one thread per output element.  K is tiled in chunks of 32 and
# staged through shared memory (sA holds a 32x32 chunk of A, sB holds a
# 32x32 chunk of B); each thread accumulates its dot product in a register.
#
# Requires M % 32 == 0, N % 32 == 0, K % 32 == 0 (true for the target
# problem: M = 32768, K = 32, N = 32768).
# ---------------------------------------------------------------------------

PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.visible .entry gemm_kernel(
    .param .u64 gemm_kernel_param_A,
    .param .u64 gemm_kernel_param_B,
    .param .u64 gemm_kernel_param_C,
    .param .u32 gemm_kernel_param_M,
    .param .u32 gemm_kernel_param_N,
    .param .u32 gemm_kernel_param_K
)
{
    .reg .pred      %p<5>;
    .reg .b32       %r<40>;
    .reg .b64       %rd<40>;
    .reg .f32       %f<10>;

    .shared .align 4 .b8 sA[4096];   // 32 x 32 floats
    .shared .align 4 .b8 sB[4096];   // 32 x 32 floats

    ld.param.u64 %rd1, [gemm_kernel_param_A];
    ld.param.u64 %rd2, [gemm_kernel_param_B];
    ld.param.u64 %rd3, [gemm_kernel_param_C];
    ld.param.u32 %r1,  [gemm_kernel_param_M];
    ld.param.u32 %r2,  [gemm_kernel_param_N];
    ld.param.u32 %r3,  [gemm_kernel_param_K];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;

    mov.u32 %r4, %ctaid.x;   // bn : N-tile index
    mov.u32 %r5, %ctaid.y;   // bm : M-tile index
    mov.u32 %r6, %tid.x;     // tx : column within tile (0..31)
    mov.u32 %r7, %tid.y;     // ty : row within tile    (0..31)

    // row = bm*32 + ty ; col = bn*32 + tx
    shl.b32 %r8, %r5, 5;
    add.s32 %r8, %r8, %r7;      // row (m)

    shl.b32 %r9, %r4, 5;
    add.s32 %r9, %r9, %r6;      // col (n)

    mov.u32 %r10, sA;
    mov.u32 %r11, sB;

    // &sA[ty][tx], &sB[ty][tx]  (store targets during load stage)
    shl.b32 %r12, %r7, 5;
    add.s32 %r12, %r12, %r6;
    shl.b32 %r13, %r12, 2;
    add.s32 %r14, %r10, %r13;
    add.s32 %r15, %r11, %r13;

    // &sA[ty][0] (row base, used during compute stage)
    shl.b32 %r16, %r7, 5;
    shl.b32 %r16, %r16, 2;
    add.s32 %r16, %r10, %r16;

    // &sB[0][tx] (col base, used during compute stage)
    shl.b32 %r17, %r6, 2;
    add.s32 %r17, %r11, %r17;

    shr.u32 %r18, %r3, 5;       // number of K tiles = K/32
    mov.f32 %f1, 0f00000000;    // accumulator

    mov.u32 %r19, 0;            // kt loop counter

LOOP_KT:
    setp.ge.u32 %p1, %r19, %r18;
    @%p1 bra LOOP_KT_END;

    // Load A[row, kt*32+tx] -> sA[ty][tx]
    shl.b32 %r20, %r19, 5;
    add.s32 %r20, %r20, %r6;
    cvt.s64.s32 %rd4, %r8;
    cvt.s64.s32 %rd5, %r3;
    mul.lo.s64 %rd6, %rd4, %rd5;
    cvt.s64.s32 %rd7, %r20;
    add.s64 %rd6, %rd6, %rd7;
    shl.b64 %rd6, %rd6, 2;
    add.s64 %rd8, %rd1, %rd6;
    ld.global.f32 %f2, [%rd8];
    st.shared.f32 [%r14], %f2;

    // Load B[kt*32+ty, col] -> sB[ty][tx]
    shl.b32 %r21, %r19, 5;
    add.s32 %r21, %r21, %r7;
    cvt.s64.s32 %rd9, %r21;
    cvt.s64.s32 %rd10, %r2;
    mul.lo.s64 %rd11, %rd9, %rd10;
    cvt.s64.s32 %rd12, %r9;
    add.s64 %rd11, %rd11, %rd12;
    shl.b64 %rd11, %rd11, 2;
    add.s64 %rd13, %rd2, %rd11;
    ld.global.f32 %f3, [%rd13];
    st.shared.f32 [%r15], %f3;

    bar.sync 0;

    // acc += sum_kk sA[ty][kk] * sB[kk][tx]
    mov.u32 %r22, 0;
    mov.u32 %r23, %r16;
    mov.u32 %r24, %r17;
LOOP_KK:
    setp.ge.u32 %p2, %r22, 32;
    @%p2 bra LOOP_KK_END;

    ld.shared.f32 %f4, [%r23];
    ld.shared.f32 %f5, [%r24];
    fma.rn.f32 %f1, %f4, %f5, %f1;

    add.s32 %r23, %r23, 4;      // next column within sA row
    add.s32 %r24, %r24, 128;    // next row within sB (32 floats * 4 bytes)
    add.s32 %r22, %r22, 1;
    bra LOOP_KK;
LOOP_KK_END:

    bar.sync 0;
    add.s32 %r19, %r19, 1;
    bra LOOP_KT;
LOOP_KT_END:

    // C[row, col] = acc
    cvt.s64.s32 %rd14, %r8;
    cvt.s64.s32 %rd15, %r2;
    mul.lo.s64 %rd16, %rd14, %rd15;
    cvt.s64.s32 %rd17, %r9;
    add.s64 %rd16, %rd16, %rd17;
    shl.b64 %rd16, %rd16, 2;
    add.s64 %rd18, %rd3, %rd16;
    st.global.f32 [%rd18], %f1;

    ret;
}
"""

_KERNEL_NAME = "gemm_kernel"
_TILE = 32

_module_singleton = None


def _get_module():
    global _module_singleton
    if _module_singleton is None:
        _module_singleton = PtxModule(PTX_SOURCE)
    return _module_singleton


def validate_generated_code():
    """Look up the kernel entry point to make sure the PTX module is valid."""
    module = _get_module()
    fn = module.function(_KERNEL_NAME)
    assert fn is not None, f"Entry point '{_KERNEL_NAME}' not found in PTX module"
    return fn


class ModelNew(nn.Module):
    """
    Performs C = A @ B using a hand-written PTX tiled GEMM kernel executed
    through cutegen.ptx_runtime.PtxModule.
    """

    def __init__(self) -> None:
        super().__init__()
        self._module = None

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.is_cuda and B.is_cuda, "A and B must be CUDA tensors"
        assert A.dim() == 2 and B.dim() == 2, "A and B must be 2D"
        assert A.dtype == torch.float32 and B.dtype == torch.float32, "Expect float32 tensors"

        A_c = A.contiguous()
        B_c = B.contiguous()

        M = A_c.shape[0]
        K = A_c.shape[1]
        N = B_c.shape[1]
        assert B_c.shape[0] == K, "Inner dimensions of A and B must match"
        assert M % _TILE == 0, f"M must be a multiple of {_TILE}"
        assert N % _TILE == 0, f"N must be a multiple of {_TILE}"
        assert K % _TILE == 0, f"K must be a multiple of {_TILE}"

        C = torch.empty((M, N), dtype=torch.float32, device=A.device)

        module = _get_module()

        grid = (N // _TILE, M // _TILE, 1)
        block = (_TILE, _TILE, 1)

        stream = torch.cuda.current_stream(device=A.device).cuda_stream

        module.launch(
            _KERNEL_NAME,
            grid=grid,
            block=block,
            args=[
                u64(A_c.data_ptr()),
                u64(B_c.data_ptr()),
                u64(C.data_ptr()),
                i32(M),
                i32(N),
                i32(K),
            ],
            stream=stream,
        )

        return C
